package crdt

import (
	"encoding/json"
	"testing"

	"github.com/stretchr/testify/require"
)

// Generated by Yjs 13.6.32: client 4 pushes [Y.XmlHook("h") holding {k: "v"},
// "x"] to array "a".
const hookArrayV1 = "01030400070101610501688804000177017828000400016b0177017600"

// The toJSON output of Yjs 13.6.32 for hookV1, hookEditV1 and hookArrayV1.
const (
	hookMapJSON   = `{"hk":{"a":1,"b":"two"},"z":3}`
	hookArrayJSON = `[{"k":"v"},"x"]`
)

func hookJSONDoc(t *testing.T) *Doc {
	t.Helper()
	doc := New(WithClientID(3))
	for _, u := range []string{hookV1, hookEditV1, hookArrayV1} {
		require.NoError(t, ApplyUpdateV1(doc, mustHex(t, u), nil))
	}
	return doc
}

func requireJSONOf(t *testing.T, want string, v any) {
	t.Helper()
	got, err := json.Marshal(v)
	require.NoError(t, err)
	require.JSONEq(t, want, string(got))
}

func TestUnit_ContentType_XmlHookReadsAsItsEntries(t *testing.T) {
	doc := hookJSONDoc(t)
	m, a := doc.GetMap("m"), doc.GetArray("a")

	got, err := m.ToJSON()
	require.NoError(t, err)
	require.JSONEq(t, hookMapJSON, string(got))
	got, err = a.ToJSON()
	require.NoError(t, err)
	require.JSONEq(t, hookArrayJSON, string(got))

	requireJSONOf(t, hookMapJSON, m.Entries())
	requireJSONOf(t, hookArrayJSON, a.ToSlice())
}

func TestUnit_ContentType_XmlHookObserverValuesAreItsEntries(t *testing.T) {
	doc := New(WithClientID(3))
	for _, u := range []string{hookV1, hookEditV1} {
		require.NoError(t, ApplyUpdateV1(doc, mustHex(t, u), nil))
	}
	a, m := doc.GetArray("a"), doc.GetMap("m")

	var inserted []any
	a.Observe(func(e YArrayEvent) {
		for _, d := range e.Delta {
			if vals, ok := d.Insert.([]any); ok {
				inserted = append(inserted, vals...)
			}
		}
	})
	require.NoError(t, ApplyUpdateV1(doc, mustHex(t, hookArrayV1), nil))
	requireJSONOf(t, hookArrayJSON, inserted)

	// Yjs 13.6.32 reports the deleted hook as its type, whose toJSON is {}:
	// the delete takes its entries with it, as for a deleted nested YMap.
	var old any
	m.Observe(func(e YMapEvent) { old = e.Keys["hk"].OldValue })
	doc.Transact(func(txn *Transaction) { m.Delete(txn, "hk") })
	requireJSONOf(t, `{}`, old)
}
